            printf("tspin 5.6.0\n");
            return 0;
        } else if (strcmp(a, "-f") == 0 || strcmp(a, "--follow") == 0) {
            follow = 1;
        } else if (strcmp(a, "-p") == 0 || strcmp(a, "--print") == 0) {
