        } else if (strcmp(a, "-e") == 0 || strcmp(a, "--exec") == 0) {
            if (i+1 < argc) { exec_cmd = argv[++i]; }
        } else if (strcmp(a, "--disable-builtin-keywords") == 0) {
            disable_builtin = 1;
        } else if (strcmp(a, "--pager") == 0) {
            if (i+1 < argc) { pager = argv[++i]; }
        } else if (strncmp(a, "--", 2) == 0) {
            // skip options with values like --highlight, --enable, --disable
            if (strcmp(a, "--highlight") == 0 || strcmp(a, "--enable") == 0 || strcmp(a, "--disable") == 0) {
                if (i+1 < argc) ++i;
            }
            // ignore unknown long options
        } else if (a[0] == '-') {
            // unknown short flags, ignore
        } else {
            // positional
            if (!file_arg) file_arg = a;
        }
    }

