    if (exec_cmd) {
        FILE *pipe = popen(exec_cmd, "r");
        if (!pipe) return 1;
        char buf[8192];
        while (fgets(buf, sizeof(buf), pipe)) {
            fputs(buf, stdout);
        }
        pclose(pipe);
        return 0;
    }

    // If there's data on stdin (piped) then print it
    if (!isatty(fileno(stdin))) {
        char buf[8192];
        while (fgets(buf, sizeof(buf), stdin)) {
            fputs(buf, stdout);
        }
        return 0;
    }

