        FILE *f = fopen(file_arg, "r");
        if (!f) {
            fprintf(stderr, "failed to open file: %s\n", file_arg);
            return 2;
        }
        if (print_out || pager == NULL) {
            char buf[8192];
            while (fgets(buf, sizeof(buf), f)) fputs(buf, stdout);
            fclose(f);
            return 0;
        } else {
            // attempt to run pager replacing [FILE]
            const char *envpager = getenv("TAILSPIN_PAGER");
            const char *usepager = envpager ? envpager : pager;
            if (!usepager) usepager = "less [FILE]";
            // build command
            size_t len = strlen(usepager) + strlen(file_arg) + 32;
            char *cmd = malloc(len);
            if (!cmd) { fclose(f); return 1; }
            // replace [FILE] with file_arg
            const char *p = usepager;
            char *q = cmd; size_t remain = len;
            while (*p && remain > 1) {
                if (p[0] == '[' && strncmp(p, "[FILE]", 6) == 0) {
                    int n = snprintf(q, remain, "%s", file_arg);
                    q += n; remain -= n; p += 6;
                } else {
                    *q++ = *p++;
                    remain--;
                }
            }
            *q = '\0';
            fclose(f);
            int rc = system(cmd);
            free(cmd);
            return rc == -1 ? 1 : WEXITSTATUS(rc);
        }
    }

    // No input provided: print help summary (short)
    printf("A log file highlighter\n\nUsage: executable [OPTIONS] [FILE]\n");
    return 0;
}
